<?= $this->extend('layouts/app') ?>
<?= $this->section('content') ?>
<section class="dashboard-intro"><div class="page-heading compact"><p class="eyebrow">STORE MANAGEMENT</p><h1><?= esc($spec['title']) ?></h1><p class="lead"><?= $resource === 'products' ? 'Manage your products, prices, stock, and prepared product images.' : ($resource === 'customers' ? 'Keep customer contact information close at hand.' : 'Manage staff profiles, avatars, and secure login credentials.') ?></p></div><a class="button" href="<?= site_url($resource.'/create') ?>">Add <?= esc(strtolower($spec['singular'])) ?> &rarr;</a></section>
<div class="directory-tabs"><a class="<?= ! $archived ? 'selected' : '' ?>" href="<?= site_url($resource) ?>">Active records</a><a class="<?= $archived ? 'selected' : '' ?>" href="<?= site_url($resource.'?archived=1') ?>">Archived records</a></div>
<section class="directory"><div class="table-top"><h2><?= $archived ? 'Archived' : 'All active' ?> <?= esc(strtolower($spec['title'])) ?></h2><span class="pill"><?= count($rows) ?> records</span></div><div class="table-scroll" tabindex="0" role="region" aria-label="<?= esc($spec['title']) ?> table"><table><thead><tr><th>ID</th><?php if ($spec['image']): ?><th>Picture</th><?php endif ?><?php foreach ($spec['fields'] as $key => [$label]): ?><?php if ($key !== 'password'): ?><th><?= esc($label) ?></th><?php endif ?><?php endforeach ?><th>Actions</th></tr></thead><tbody>
<?php foreach ($rows as $row): ?><tr><td class="muted"><?= $row['id'] ?></td><?php if ($spec['image']): ?><td><img class="<?= $resource === 'staff' ? 'avatar' : 'product-thumb' ?>" src="<?= record_image($row[$spec['image']], $spec['kind']) ?>" alt="<?= esc($row['name'] ?? $row['full_name'], 'attr') ?>" width="<?= $resource === 'staff' ? 48 : 72 ?>" height="48"></td><?php endif ?>
<?php foreach ($spec['fields'] as $key => [$label]): ?><?php if ($key !== 'password'): ?><td><?php if ($key === 'price'): ?>&#8369;<?= peso($row[$key]) ?><?php elseif ($key === 'stock_quantity'): ?><span class="stock-badge <?= $row[$key] == 0 ? 'out' : '' ?>"><?= (int) $row[$key] ?></span><?php else: ?><?= esc($row[$key] ?? '—') ?><?php endif ?></td><?php endif ?><?php endforeach ?>
<td><?php if (! $archived): ?><div class="row-actions"><a class="text-link" href="<?= site_url($resource.'/'.$row['id'].'/edit') ?>">Edit</a><?php if ($resource !== 'staff' || (int) $row['id'] !== (int) session()->get('staff_id')): ?><a class="remove-link" href="<?= site_url($resource.'/'.$row['id'].'/remove') ?>">Remove</a><?php else: ?><span class="pill">You</span><?php endif ?></div><?php else: ?><span class="muted">History preserved</span><?php endif ?></td></tr><?php endforeach ?>
<?php if (! $rows): ?><tr><td colspan="8" class="empty-state">No <?= $archived ? 'archived' : 'active' ?> records yet.</td></tr><?php endif ?>
</tbody></table></div><p class="table-note">Records referenced by sales are archived when removed to preserve transaction history.</p></section>
